Pattern optionalPattern = Pattern.compile('([A-Z]+)([0-9]+)?');
Matcher optional = optionalPattern.matcher('ABC');
System.assert(optional.matches());
System.assertEquals(null, optional.group(2));
System.assertEquals(-1, optional.start(2));
System.assertEquals(-1, optional.end(2));
Pattern word = Pattern.compile('[A-Z]+');
Matcher full = word.matcher('ABC def');
System.assert(full.find());
System.assertEquals('ABC', full.group());
System.assert(!full.matches());
full.reset();
System.assert(full.find());
System.assertEquals('ABC', full.group());
Matcher head = word.matcher('ABC def');
System.assert(head.find());
head.reset('abc DEF');
System.assert(!head.lookingAt());
System.assert(head.find());
System.assertEquals('DEF', head.group());

